#include "frame_bench.h"
#include <iostream>
#include "trace_cli.h"
int main(int argc,char **argv) {
    trace::Arguments arguments(argc,argv);argc=int(arguments.words.size());argv=arguments.pointers.data();
    try {
        bench::Args a;std::map<std::string,std::string> opts;int runs=5;std::filesystem::path output;
        for(int i=1;i<argc;++i){std::string k=argv[i];if(k=="--interpreter"){a.interpreter=true;continue;}if(k=="--help"){std::cout<<"Usage: frame-bench --before FILE --after FILE --exe FILE --script FILE --card FILE --output DIR --disc FILE [--first N] [--last N] [--runs N] [--renderer soft|vulkan] [--interpreter] [--before-state FILE] [--after-state FILE]\n";return 0;}iro::require(i+1<argc,"missing option value");std::string v=argv[++i];if(k=="--disc")a.discs.emplace_back(v);else {iro::require(k=="--before"||k=="--after"||k=="--exe"||k=="--script"||k=="--card"||k=="--output"||k=="--first"||k=="--last"||k=="--runs"||k=="--renderer"||k=="--before-state"||k=="--after-state","unknown option");opts[k]=v;}}
        for(const char *k:{"--before","--after","--exe","--script","--card","--output"})iro::require(opts.count(k),(std::string(k)+" is required").c_str());iro::require(!a.discs.empty(),"--disc is required");
        a.card=opts.at("--card");a.exe=opts.at("--exe");a.script=opts.at("--script");output=std::filesystem::weakly_canonical(opts.at("--output"));
        if(opts.count("--first"))a.first=std::stoi(opts.at("--first"));if(opts.count("--last"))a.last=std::stoi(opts.at("--last"));if(opts.count("--runs"))runs=std::stoi(opts.at("--runs"));if(opts.count("--renderer"))a.renderer=opts.at("--renderer");iro::require(a.renderer=="soft"||a.renderer=="vulkan","invalid renderer");iro::require(1<=a.first&&a.first<=a.last&&runs>=1,"require 1 <= first <= last and at least one pair");
        std::map<std::string,std::vector<dt::Json>> receipts;std::string work;
        for(int repeat=0;repeat<runs;++repeat)for(const char *side:{"before","after"}){std::ostringstream name;name<<std::setfill('0')<<std::setw(2)<<repeat<<'-'<<side;auto r=bench::measure(opts.at("--"+std::string(side)),a,output/name.str(),opts["--"+std::string(side)+"-state"]);receipts[side].push_back(r);dt::Json line=dt::Json::Object{{"repeat",repeat},{"side",side}};for(const auto &p:std::get<dt::Json::Object>(r.value))line.set(p.first,p.second);std::cout<<line.dump()<<std::endl;auto hash=std::get<std::string>(r.at("work_sha256").value);if(work.empty())work=hash;iro::require(work==hash,"guest work changed between runs");}
        dt::Json results=dt::Json::object();for(const char *side:{"before","after"}){dt::Json clocks=dt::Json::object();for(const char *clock:{"cpu_ms","wall_ms"}){dt::Json keys=dt::Json::object();for(const auto &p:std::get<dt::Json::Object>(receipts[side][0].at(clock).value)){std::vector<double> v;bool integer=std::holds_alternative<int64_t>(p.second.value);for(const auto &r:receipts[side]){const auto &j=r.at(clock).at(p.first);v.push_back(integer?double(std::get<int64_t>(j.value)):std::get<double>(j.value));}std::sort(v.begin(),v.end());dt::Json median=v.size()%2?(integer?dt::Json(int64_t(v[v.size()/2])):dt::Json(v[v.size()/2])):dt::Json((v[v.size()/2-1]+v[v.size()/2])/2);keys.set(p.first,dt::Json::Object{{"median",median},{"min",integer?dt::Json(int64_t(v.front())):dt::Json(v.front())},{"max",integer?dt::Json(int64_t(v.back())):dt::Json(v.back())}});}clocks.set(clock,keys);}results.set(side,clocks);}dt::write(output/"summary.json",dt::Json(dt::Json::Object{{"runs_per_side",runs},{"matched_work",true},{"results",results}}).dump(2)+"\n");
    }catch(const std::exception &e){std::cerr<<"frame-bench: "<<e.what()<<'\n';return 1;}
}
